function CI.IconPath(b)
    if b and (b.zoneId or 0) > 0 then return ZONE_ICON[b.zoneId] or ICON_ZONE end -- open-world zone
    local tex = b and b.mapId and MAP_ICON[b.mapId]
    return tex and (ICON_PATH .. tex) or ICON_FALLBACK
end
